struct Child;
struct Parent {
    std::shared_ptr<Child> child;    // owns
    ~Parent() { std::cout << "~Parent\n"; }
};
struct Child {
    std::weak_ptr<Parent> parent;    // only observes
    ~Child() { std::cout << "~Child\n"; }
};
int main() {
    auto p = std::make_shared<Parent>();
    p->child = std::make_shared<Child>();
    p->child->parent = p;
}
